from collections import Counter

def _runs(values, color):
    out = []
    i = 0
    while i < len(values):
        if values[i] != color:
            i += 1
            continue
        j = i
        while j + 1 < len(values) and values[j + 1] == color:
            j += 1
        out.append((i, j))
        i = j + 1
    return out

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    edge_colors = [g[r][c] for r in range(h) for c in (0, w - 1) if g[r][c] != bg]
    edge_colors += [g[r][c] for r in (0, h - 1) for c in range(w) if g[r][c] != bg]
    rail = Counter(edge_colors).most_common(1)[0][0]

    # Runs on each pair of opposite borders form matching portals.
    left = _runs([g[r][0] for r in range(h)], rail)
    right = _runs([g[r][w - 1] for r in range(h)], rail)
    top = _runs(g[0], rail)
    bottom = _runs(g[h - 1], rail)
    markers = [(r, c, g[r][c]) for r in range(h) for c in range(w)
               if g[r][c] != bg and g[r][c] != rail]

    def paint(r, c, color):
        if g[r][c] == bg:
            g[r][c] = color

    if left and right:
        for r, c, color in markers:
            hit = next(((i, a, b) for i, (a, b) in enumerate(left) if a <= r <= b), None)
            toward_left = hit is not None
            if hit is None:
                hit = next(((i, a, b) for i, (a, b) in enumerate(right) if a <= r <= b), None)
                toward_left = False
            if hit is None:
                continue
            i, a, b = hit
            paired = right if toward_left else left
            if i >= len(paired):
                continue
            u, v = paired[i]
            mapped = u + (r - a)
            # Draw from the marker into its aligned portal.
            if toward_left:
                for cc in range(c - 1, -1, -1): paint(r, cc, color)
                # Re-enter at the paired portal and continue leftward to the edge.
                for cc in range(w - 1, -1, -1): paint(mapped, cc, color)
            else:
                for cc in range(c + 1, w): paint(r, cc, color)
                for cc in range(w): paint(mapped, cc, color)
            g[r][c] = 4
        return g

    if top and bottom:
        for r, c, color in markers:
            hit = next(((i, a, b) for i, (a, b) in enumerate(top) if a <= c <= b), None)
            toward_top = hit is not None
            if hit is None:
                hit = next(((i, a, b) for i, (a, b) in enumerate(bottom) if a <= c <= b), None)
                toward_top = False
            if hit is None:
                continue
            i, a, b = hit
            paired = bottom if toward_top else top
            if i >= len(paired):
                continue
            u, v = paired[i]
            mapped = u + (c - a)
            if toward_top:
                for rr in range(r - 1, -1, -1): paint(rr, c, color)
                for rr in range(h - 1, -1, -1): paint(rr, mapped, color)
            else:
                for rr in range(r + 1, h): paint(rr, c, color)
                for rr in range(h): paint(rr, mapped, color)
            g[r][c] = 4
    return g
